#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int minMaxComponentCost(int n, std::vector<std::vector<int>>& edges, int k) {
        if (k >= n - 1) return 0;
        std::vector<std::vector<int>> sorted_edges = edges;
        std::sort(sorted_edges.begin(), sorted_edges.end(), [](const auto& a, const auto& b) {
            return a[2] < b[2];
        });

        std::vector<int> parent(n);
        std::iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto& self, int x) -> int {
            return parent[x] == x ? x : parent[x] = self(self, parent[x]);
        };

        auto unite = [&](int x, int y) {
            int rx = find(find, x), ry = find(find, y);
            if (rx != ry) {
                parent[rx] = ry;
                return true;
            }
            return false;
        };

        int components = n;
        int target = k + 1;
        int max_cost = 0;

        for (const auto& e : sorted_edges) {
            if (components <= target) break;
            if (unite(e[0], e[1])) {
                components--;
                max_cost = std::max(max_cost, e[2]);
            }
        }

        return max_cost;
    }
};

import java.util.*;

class Solution {
    public int minMaxComponentCost(int n, int[][] edges, int k) {
        if (k >= n - 1) return 0;
        Arrays.sort(edges, Comparator.comparingInt(a -> a[2]));

        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        int components = n;
        int target = k + 1;
        int maxCost = 0;

        for (int[] e : edges) {
            if (components <= target) break;
            if (union(parent, e[0], e[1])) {
                components--;
                maxCost = Math.max(maxCost, e[2]);
            }
        }

        return maxCost;
    }

    private int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    private boolean union(int[] parent, int x, int y) {
        int rx = find(parent, x), ry = find(parent, y);
        if (rx != ry) {
            parent[rx] = ry;
            return true;
        }
        return false;
    }
}

