var minMaxComponentCost = function(n, edges, k) {
    if (k >= n - 1) return 0;
    const sortedEdges = edges.slice().sort((a, b) => a[2] - b[2]);

    const parent = new Int32Array(n);
    for (let i = 0; i < n; i++) parent[i] = i;

    const find = (x) => {
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    };

    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) {
            parent[rx] = ry;
            return true;
        }
        return false;
    };

    let components = n;
    const target = k + 1;
    let maxCost = 0;

    for (const [u, v, w] of sortedEdges) {
        if (components <= target) break;
        if (union(u, v)) {
            components--;
            if (w > maxCost) maxCost = w;
        }
    }

    return maxCost;
};
